{
  "name": "commentie",
  "version": "0.2.1",
  "description": "Keep code comments few, short and plain, as a Claude Code plugin and an OpenCode plugin.",
  "type": "module",
  "main": "opencode/plugin.ts",
  "exports": {
    ".": "./opencode/plugin.ts",
    "./server": "./opencode/plugin.ts"
  },
  "files": [
    "opencode",
    "scripts/check_comments.py",
    "skills",
    "agents",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "comments",
    "code-quality",
    "review",
    "claude-code",
    "opencode",
    "opencode-plugin"
  ],
  "author": {
    "name": "Mehmet Fahri Özmen"
  },
  "homepage": "https://github.com/mfozmen/commentie",
  "repository": "https://github.com/mfozmen/commentie",
  "license": "MIT",
  "engines": {
    "opencode": ">=1.19.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.19.3"
  }
}
